"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[35303],{77733:n=>{n.exports=JSON.parse('{"functions":[{"name":"formatCountdown","desc":"Formats a number of seconds as countdown text, showing only as many units as the remaining\\ntime needs: `45`, then `3:05`, then `1:02:03`, and `2 days 1:02:03` for longer waits. Each unit\\ncounts up to a round number before the next is used, so a one minute countdown starts at `60`,\\na one hour countdown at `60:00`, and a single day rolls into the hours as `47:15:00`.\\nThe `days` word is localized through [TimeDurationUtils.format]; `locale` defaults to English.\\nFractional seconds are truncated.\\n\\n```lua\\nprint(CountdownTextUtils.formatCountdown(0, \\"Now!\\")) --\x3e Now!\\nprint(CountdownTextUtils.formatCountdown(185)) --\x3e 3:05\\nprint(CountdownTextUtils.formatCountdown(3 * 86400 + 5, nil, \\"es-es\\")) --\x3e 3 d\xedas 0:00:05\\n```","params":[{"name":"seconds","desc":"","lua_type":"number"},{"name":"whenAtZeroText","desc":"","lua_type":"string?"},{"name":"locale","desc":"","lua_type":"string?"}],"returns":[{"desc":"","lua_type":"string\\n"}],"function_type":"static","source":{"line":28,"path":"src/countdowntext/src/Shared/CountdownTextUtils.lua"}}],"properties":[],"types":[],"name":"CountdownTextUtils","desc":"Utility functions to format countdowns in-game, built on [TimeDurationUtils].","source":{"line":7,"path":"src/countdowntext/src/Shared/CountdownTextUtils.lua"}}')}}]);